const config = {
  "previewFeatures": [],
  "clientVersion": "7.3.0",
  "engineVersion": "9d6ad21cbbceab97458517b147a6a09ff43aa735",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"./generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// USER MODEL (Regular Customers)\n\nmodel User {\n  id            String    @id @default(cuid())\n  email         String    @unique\n  emailVerified DateTime?\n  firstName     String\n  lastName      String\n  password      String\n  image         String?\n  phone         String?\n\n  isActive Boolean @default(true)\n\n  createdAt           DateTime  @default(now())\n  updatedAt           DateTime  @updatedAt\n  failedLoginAttempts Int?      @default(0)\n  lockedUntil         DateTime?\n  lastLoginAt         DateTime?\n  lastLoginIp         String?\n\n  // Map selection (customer)\n  // Stores selected products for the \"Add to map\" feature.\n  // Anonymous users store this in sessionStorage; signed-in users persist here.\n  mapSelectionProductIds String[] @default([])\n\n  // Relations\n  sessions Session[]\n\n  @@index([email])\n  @@map(\"users\")\n}\n\n// SELLER MODEL\nmodel Seller {\n  id       String  @id @default(cuid())\n  email    String  @unique\n  password String? // NULL until they set it up\n\n  // Profile\n  businessName  String?\n  contactPerson String?\n  phone         String?\n  description   String?\n  logoUrl       String?\n  bannerUrl     String?\n  socialLinks   Json? // { instagram, telegram, whatsapp, email }\n\n  // Status\n  isVerified  Boolean   @default(false)\n  isActive    Boolean   @default(true)\n  invitedAt   DateTime  @default(now())\n  lastLoginAt DateTime?\n\n  // Invitation\n  inviteToken  String?   @unique\n  inviteExpiry DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  shops    Shop[]\n  sessions Session[]\n\n  failedLoginAttempts Int?      @default(0)\n  lockedUntil         DateTime?\n  lastLoginIp         String?\n\n  @@index([email])\n  @@index([inviteToken])\n  @@map(\"sellers\")\n}\n\n// MALL OWNER MODEL\nmodel MallOwner {\n  id       String @id @default(cuid())\n  email    String @unique\n  password String\n\n  // Profile\n  name  String\n  phone String?\n\n  // Security\n  allowedIps          String[] // IP whitelist\n  mfaSecret           String? // For 2FA (future)\n  mfaEnabled          Boolean   @default(false)\n  failedLoginAttempts Int       @default(0)\n  lockedUntil         DateTime?\n\n  // Session management\n  lastLoginAt DateTime?\n  lastLoginIp String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  sessions Session[]\n\n  lastMagicLinkRequestedAt DateTime?\n  lastMagicLinkRequestIp   String?\n\n  @@index([email])\n  @@map(\"mall_owners\")\n}\n\n// SESSION MODEL (For all user types)\nmodel Session {\n  id           String @id @default(cuid())\n  sessionToken String @unique\n\n  // Polymorphic relations (only one will be set)\n  userId      String?\n  sellerId    String?\n  mallOwnerId String?\n\n  // Session data\n  expires   DateTime\n  ipAddress String?\n  userAgent String?\n\n  // Token rotation security\n  // Used for refresh token rotation to detect token reuse attacks\n  tokenFamily String?\n\n  // Session revocation flag\n  isRevoked Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user      User?      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  seller    Seller?    @relation(fields: [sellerId], references: [id], onDelete: Cascade)\n  mallOwner MallOwner? @relation(fields: [mallOwnerId], references: [id], onDelete: Cascade)\n\n  @@index([sessionToken])\n  @@index([userId])\n  @@index([sellerId])\n  @@index([mallOwnerId])\n  @@index([tokenFamily])\n  @@map(\"sessions\")\n}\n\n// VERIFICATION TOKEN (Email verification, magic links)\nmodel VerificationToken {\n  id         String    @id @default(cuid())\n  identifier String // Email or user ID\n  token      String    @unique\n  type       TokenType\n  expires    DateTime\n\n  createdAt DateTime @default(now())\n\n  @@unique([identifier, token])\n  @@index([token])\n  @@map(\"verification_tokens\")\n}\n\nenum TokenType {\n  EMAIL_VERIFICATION\n  PASSWORD_RESET\n  MAGIC_LINK\n  INVITATION\n}\n\n// SHOP TYPE MODEL (Database-defined types for shops/units)\nmodel ShopType {\n  id               String  @id @default(cuid())\n  key              String  @unique\n  name_en          String\n  name_ru          String\n  name_am          String?\n  icon             String?\n  color            String?\n  supportsProducts Boolean @default(true)\n  sortOrder        Int     @default(0)\n\n  shops Shop[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"shop_types\")\n}\n\n// SHOP MODEL\nmodel Shop {\n  id String @id @default(cuid())\n\n  // Location (legacy string fields - kept for backward compatibility)\n  venue      String\n  building   String?\n  floor      String?\n  shopNumber String\n  fullCode   String  @unique\n\n  // New: Direct relation to Floor entity\n  floorId  String?\n  floorRef Floor?  @relation(\"FloorShops\", fields: [floorId], references: [id], onDelete: SetNull)\n\n  // Shop type\n  shopTypeId String?\n  shopType   ShopType? @relation(fields: [shopTypeId], references: [id], onDelete: SetNull)\n\n  // Seller relation\n  sellerId String?\n\n  // Shop details\n  shopName     String?\n  description  String?\n  imageUrl     String?\n  svgId        String? // For map linking\n  coordinates  Json? // { x, y } if needed\n  openingHours Json? // { mon: \"9-18\", tue: \"9-18\", ... }\n\n  // Status\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  seller   Seller?       @relation(fields: [sellerId], references: [id], onDelete: SetNull)\n  products Product[]\n  contacts ShopContact[]\n\n  @@index([sellerId])\n  @@index([fullCode])\n  @@index([floorId])\n  @@index([shopTypeId])\n  @@map(\"shops\")\n}\n\n// PRODUCT MODEL\n\nmodel Product {\n  id     String @id @default(cuid())\n  shopId String\n\n  // Basic info (multilingual)\n  name                 String // Legacy field - kept for backward compatibility\n  name_en              String?\n  name_ru              String?\n  name_am              String?\n  description          String? // Legacy field - kept for backward compatibility\n  description_en       String?\n  description_ru       String?\n  description_am       String?\n  detailDescription    String? @db.Text // Legacy field\n  detailDescription_en String? @db.Text\n  detailDescription_ru String? @db.Text\n  detailDescription_am String? @db.Text\n\n  // Pricing & stock\n  basePrice     Decimal @db.Decimal(10, 2)\n  stockQuantity Int     @default(0)\n  unitType      String  @default(\"piece\")\n\n  // Categorization (3-level hierarchy)\n  categoryId       String?\n  subcategoryId    String?\n  subSubcategoryId String?\n  brand            String?\n  barcode          String?\n  tags             String[]\n\n  // Media (max 5 images)\n  images String[]\n\n  // Status\n  status     ProductStatus @default(DRAFT)\n  isActive   Boolean       @default(true)\n  isFeatured Boolean       @default(false)\n\n  // Timestamps\n  createdAt   DateTime @default(now())\n  lastUpdated DateTime @updatedAt\n\n  // Relations\n  shop           Shop              @relation(fields: [shopId], references: [id], onDelete: Cascade)\n  category       Category?         @relation(fields: [categoryId], references: [id])\n  subcategory    Subcategory?      @relation(fields: [subcategoryId], references: [id])\n  subSubcategory SubSubcategory?   @relation(fields: [subSubcategoryId], references: [id])\n  priceTiers     PriceTier[]\n  discounts      ProductDiscount[]\n  views          ProductView[]\n  favorites      Favorite[]\n\n  sku            String?\n  viewCount      Int      @default(0) // Legacy total count - kept for quick queries\n  weight         Decimal? @db.Decimal(10, 2)\n  specifications Json? // To handle the metadata\n\n  @@index([shopId])\n  @@index([categoryId])\n  @@index([subcategoryId])\n  @@index([subSubcategoryId])\n  @@index([status])\n  @@index([barcode])\n  @@index([sku])\n  @@map(\"products\")\n}\n\n// FAVORITE (Wishlist)\nmodel Favorite {\n  id        String   @id @default(cuid())\n  ownerId   String\n  ownerRole String\n  productId String\n  createdAt DateTime @default(now())\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([ownerId, productId])\n  @@index([ownerId, createdAt(sort: Desc)])\n  @@index([productId])\n  @@map(\"favorites\")\n}\n\n// PRODUCT VIEW (For analytics with timestamps)\nmodel ProductView {\n  id        String @id @default(cuid())\n  productId String\n\n  // Optional user tracking (null for anonymous views)\n  userId String?\n\n  // View metadata\n  ipAddress String?\n  userAgent String?\n  referrer  String?\n\n  viewedAt DateTime @default(now())\n\n  // Relations\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([productId, viewedAt])\n  @@index([viewedAt])\n  @@map(\"product_views\")\n}\n\nenum ProductStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\n// PRICE TIER (Wholesale pricing)\n\nmodel PriceTier {\n  id          String  @id @default(cuid())\n  productId   String\n  minQuantity Int\n  maxQuantity Int?\n  price       Decimal @db.Decimal(10, 2)\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"price_tiers\")\n}\n\n// PRODUCT DISCOUNT\nmodel ProductDiscount {\n  id            String    @id @default(cuid())\n  productId     String\n  name          String\n  name_en       String?\n  name_ru       String?\n  name_am       String?\n  discountType  String    @default(\"percentage\") // percentage | fixed\n  discountValue Decimal   @db.Decimal(10, 2)\n  startDate     DateTime?\n  endDate       DateTime?\n  isActive      Boolean   @default(true)\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_discounts\")\n}\n\n// SHOP CONTACT\n\nmodel ShopContact {\n  id     String      @id @default(cuid())\n  shopId String\n  type   ContactType\n  value  String\n  label  String?\n\n  shop Shop @relation(fields: [shopId], references: [id], onDelete: Cascade)\n\n  @@index([shopId])\n  @@map(\"shop_contacts\")\n}\n\nenum ContactType {\n  PHONE\n  EMAIL\n  WHATSAPP\n  TELEGRAM\n  INSTAGRAM\n  FACEBOOK\n  VK\n  TIKTOK\n  YOUTUBE\n  SNAPCHAT\n  X_TWITTER\n}\n\n// CATEGORY (Level 1)\n\nmodel Category {\n  id      String  @id @default(cuid())\n  key     String  @unique\n  name_en String\n  name_ru String\n  name_am String? // Armenian translation\n  icon    String?\n\n  products      Product[]\n  subcategories Subcategory[]\n\n  @@map(\"categories\")\n}\n\n// SUBCATEGORY (Level 2)\n\nmodel Subcategory {\n  id         String  @id @default(cuid())\n  key        String  @unique\n  name_en    String\n  name_ru    String\n  name_am    String? // Armenian translation\n  categoryId String\n\n  category         Category         @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  products         Product[]\n  subSubcategories SubSubcategory[]\n\n  @@index([categoryId])\n  @@map(\"subcategories\")\n}\n\n// SUBSUBCATEGORY (Level 3)\n\nmodel SubSubcategory {\n  id            String  @id @default(cuid())\n  key           String  @unique\n  name_en       String\n  name_ru       String\n  name_am       String? // Armenian translation\n  subcategoryId String\n\n  subcategory Subcategory @relation(fields: [subcategoryId], references: [id], onDelete: Cascade)\n  products    Product[]\n\n  @@index([subcategoryId])\n  @@map(\"sub_subcategories\")\n}\n\n// MALL MODEL (Central location data)\nmodel Mall {\n  id        String  @id @default(cuid())\n  name      String\n  latitude  Float // Center point for map focus\n  longitude Float\n  address   String?\n\n  // About page content (editable by mall owner)\n  description_en String?\n  description_ru String?\n  description_am String?\n  workingHours   String? // e.g. \"Mon-Sat: 10:00-21:00, Sun: 11:00-20:00\"\n  contactPhone   String?\n  contactEmail   String?\n  logoUrl        String?\n  socialLinks    Json? // { instagram?: string, facebook?: string, telegram?: string }\n  policies_en    String? // Return/exchange policies\n  policies_ru    String?\n  policies_am    String?\n\n  buildings Building[]\n  venues    Venue[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"malls\")\n}\n\n// BUILDING MODEL (Physical structures with geo-positioning)\nmodel Building {\n  id     String @id @default(cuid())\n  mallId String\n  mall   Mall   @relation(fields: [mallId], references: [id], onDelete: Cascade)\n\n  // Venue relation - buildings belong to a venue\n  venueId String\n  venue   Venue  @relation(fields: [venueId], references: [id], onDelete: Cascade)\n\n  name String // \"Building 1\", \"Main Hall\"\n  code String // \"B1\", \"B2\" (for SVG ID matching)\n\n  // Geo-positioning (all floors of this building share this position)\n  latitude  Float\n  longitude Float\n  rotation  Float @default(0) // Degrees 0-360\n  scale     Float @default(1) // Scale factor for SVG overlay\n\n  floors Floor[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([mallId, code])\n  @@index([mallId])\n  @@index([venueId])\n  @@map(\"buildings\")\n}\n\n// VENUE MODEL (Top-level container for buildings)\nmodel Venue {\n  id     String @id @default(cuid())\n  mallId String\n  mall   Mall   @relation(fields: [mallId], references: [id], onDelete: Cascade)\n\n  name String // \"Main Complex\", \"North Wing\", \"Outdoor Area\"\n  code String // \"V1\", \"V2\" (for SVG ID matching)\n\n  // Geo-positioning (center point for this venue)\n  latitude  Float\n  longitude Float\n\n  // SVG map overlay (optional - venues can have an outdoor area map)\n  svgUrl  String?\n  shopIds String[] @default([])\n\n  // Geo-positioning for SVG overlay\n  rotation Float @default(0)\n  scale    Float @default(1)\n\n  // Wayfinding data for outdoor navigation (optional)\n  wayfindingData Json?\n\n  // Buildings in this venue\n  buildings Building[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([mallId, code])\n  @@index([mallId])\n  @@map(\"venues\")\n}\n\n// FLOOR MODEL (Physical floor level within a building)\nmodel Floor {\n  id         String   @id @default(cuid())\n  buildingId String\n  building   Building @relation(fields: [buildingId], references: [id], onDelete: Cascade)\n\n  number Int // 1, 2, 3... (0 for ground level if needed)\n  label  String? // Optional: \"Ground Floor\", \"Level 2\", \"Basement\"\n  code   String // \"F1\", \"F2\" (for display and SVG ID matching)\n\n  // Per-floor geo-positioning (nullable — falls back to building-level if null)\n  latitude  Float?\n  longitude Float?\n  rotation  Float? @default(0)\n  scale     Float? @default(1)\n\n  // Relations\n  floorMap FloorMap?\n  shops    Shop[]    @relation(\"FloorShops\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([buildingId, number])\n  @@unique([buildingId, code])\n  @@index([buildingId])\n  @@map(\"floors\")\n}\n\n// FLOOR MAP (SVG for a specific floor of a building)\nmodel FloorMap {\n  id      String @id @default(cuid())\n  floorId String @unique\n  floor   Floor  @relation(fields: [floorId], references: [id], onDelete: Cascade)\n\n  svgUrl  String\n  shopIds String[] @default([]) // Parsed SVG element IDs for quick reference\n\n  // Wayfinding data for indoor navigation\n  // JSON structure: { vertices: [...], edges: [...], entrances: [...] }\n  // See src/lib/wayfinding/types.ts for WayfindingData interface\n  wayfindingData Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([floorId])\n  @@map(\"floor_maps\")\n}\n\nmodel AuditLog {\n  id           String   @id @default(cuid())\n  action       String\n  userId       String?\n  userEmail    String?\n  userRole     String?\n  ipAddress    String?\n  userAgent    String?\n  details      Json?\n  success      Boolean  @default(true)\n  errorMessage String?\n  createdAt    DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n"
}

